import json
import sys
from collections import defaultdict

def solve(lines: list[str]) -> str:
    VALID_KEYS = {"Depends", "Before", "After", "Needs", "Requires", "Alias", "Phony"}

    # Phase 1: Input Parsing and Validation
    blocks = []  # list of (block_type, name, override_id_or_None, directives_list)
    current_block = None

    for line in lines:
        stripped = line.strip()
        # Skip blank lines and comments
        if stripped == "" or stripped.startswith("#"):
            continue
        # Check for section headers like [Task] - ignore them
        if stripped.startswith("[") and stripped.endswith("]"):
            continue

        # Check if it's a header
        tokens = stripped.split()
        if tokens[0] == "TARGET":
            if len(tokens) != 2:
                return "PARSE_ERROR"
            if current_block is not None:
                blocks.append(current_block)
            current_block = ("TARGET", tokens[1], None, [])
        elif tokens[0] == "OVERRIDE":
            if len(tokens) != 3:
                return "PARSE_ERROR"
            if current_block is not None:
                blocks.append(current_block)
            current_block = ("OVERRIDE", tokens[1], tokens[2], [])
        elif current_block is not None and "=" in stripped:
            # Directive line
            if stripped.count("=") != 1:
                return "PARSE_ERROR"
            key, value = stripped.split("=", 1)
            key = key.strip()
            value = value.strip()
            if key not in VALID_KEYS:
                return "PARSE_ERROR"
            if key == "Phony":
                if value not in ("yes", "no"):
                    return "PARSE_ERROR"
            current_block[3].append((key, value))
        else:
            return "PARSE_ERROR"

    if current_block is not None:
        blocks.append(current_block)

    # Phase 2: Universe Construction
    defined_targets = set()
    referenced_targets = set()
    all_aliases = []  # list of (a, b) pairs

    for block_type, name, override_id, directives in blocks:
        defined_targets.add(name)
        for key, value in directives:
            if key in ("Depends", "Before", "After", "Needs", "Requires", "Alias"):
                if value:
                    for t in value.split():
                        referenced_targets.add(t)
                        if key == "Alias":
                            all_aliases.append((name, t))

    universe = defined_targets | referenced_targets

    # Phase 3: Alias Resolution and Canonicalization
    # Build union-find for aliases
    parent = {t: t for t in universe}

    def find(x):
        while parent[x] != x:
            parent[x] = parent[parent[x]]
            x = parent[x]
        return x

    def union(a, b):
        ra, rb = find(a), find(b)
        if ra != rb:
            # Always merge - we'll pick lex smallest later
            parent[ra] = rb

    # Also add alias targets to universe if not already there
    for a, b in all_aliases:
        if a not in universe:
            universe.add(a)
            parent[a] = a
        if b not in universe:
            universe.add(b)
            parent[b] = b
        union(a, b)

    # Build components and find canonical names
    components = defaultdict(set)
    for t in universe:
        components[find(t)].add(t)

    # Also re-find after all unions
    components2 = defaultdict(set)
    for t in universe:
        components2[find(t)].add(t)

    canonical_map = {}
    for root, members in components2.items():
        canon = min(members)
        for m in members:
            canonical_map[m] = canon

    # Replace all target names with canonical names
    def canon(name):
        return canonical_map.get(name, name)

    # Phase 4: Directive Accumulation
    # For each target (by canonical name), collect all blocks
    target_blocks = defaultdict(list)  # canonical_name -> list of (processing_order, block)

    # Separate TARGET and OVERRIDE blocks
    target_blocks_list = []  # (block_type, name, override_id, directives, original_index)
    for i, (bt, name, oid, dirs) in enumerate(blocks):
        target_blocks_list.append((bt, name, oid, dirs, i))

    # Group by canonical target name
    target_block_groups = defaultdict(list)
    for bt, name, oid, dirs, idx in target_blocks_list:
        cname = canon(name)
        if bt == "TARGET":
            target_block_groups[cname].append(("TARGET", idx, dirs))
        else:
            target_block_groups[cname].append(("OVERRIDE", oid, dirs))

    # Process and accumulate directives for each target
    target_directives = {}  # canonical_name -> {key: value}

    for cname in universe:
        group = target_block_groups.get(cname, [])
        target_dirs = group

        # Sort: TARGET blocks by appearance order, OVERRIDE blocks by id
        target_parts = [(0, idx, dirs) for bt, idx, dirs in target_dirs if bt == "TARGET"]
        override_parts = [(1, oid, dirs) for bt, oid, dirs in target_dirs if bt == "OVERRIDE"]

        target_parts.sort(key=lambda x: x[1])
        override_parts.sort(key=lambda x: x[1])

        ordered = target_parts + override_parts

        acc = defaultdict(set)
        phony = None

        for _, _, dirs in ordered:
            for key, value in dirs:
                if key == "Phony":
                    phony = value
                elif key in ("Depends", "Before", "After", "Needs", "Requires"):
                    if value:
                        for t in value.split():
                            acc[key].add(canon(t))
                elif key == "Alias":
                    if value:
                        for t in value.split():
                            acc[key].add(canon(t))

        if phony is None:
            phony = "no"

        target_directives[cname] = (dict(acc), phony)

    # Phase 5: Dependency Graph Construction
    graph = defaultdict(set)  # adjacency list
    for t in universe:
        graph[t]  # ensure all nodes exist

    for cname in universe:
        acc, phony = target_directives.get(cname, ({}, "no"))
        for key in ("Depends", "After"):
            for dep in acc.get(key, set()):
                graph[dep].add(cname)  # dep -> cname
        for key in ("Before", "Needs", "Requires"):
            for dep in acc.get(key, set()):
                graph[cname].add(dep)  # cname -> dep

    # Phase 6: Cycle Detection - Find SCCs using Tarjan's algorithm
    index_counter = [0]
    stack = []
    on_stack = set()
    indices = {}
    lowlinks = {}
    sccs = []

    def strongconnect(v):
        indices[v] = index_counter[0]
        lowlinks[v] = index_counter[0]
        index_counter[0] += 1
        stack.append(v)
        on_stack.add(v)

        for w in graph[v]:
            if w not in indices:
                strongconnect(w)
                lowlinks[v] = min(lowlinks[v], lowlinks[w])
            elif w in on_stack:
                lowlinks[v] = min(lowlinks[v], indices[w])

        if lowlinks[v] == indices[v]:
            scc = []
            while True:
                w = stack.pop()
                on_stack.remove(w)
                scc.append(w)
                if w == v:
                    break
            sccs.append(scc)

    sys.setrecursionlimit(100000)
    for v in sorted(universe):
        if v not in indices:
            strongconnect(v)

    # Find cycles
    cycles = []
    for scc in sccs:
        is_cycle = False
        if len(scc) >= 2:
            is_cycle = True
        elif len(scc) == 1:
            v = scc[0]
            if v in graph[v]:
                is_cycle = True
        if is_cycle:
            cycles.append(sorted(scc))

    cycles.sort()

    # Phase 7: Topological Ordering
    # Build condensation DAG
    scc_index = {}  # node -> scc index
    for i, scc in enumerate(sccs):
        for v in scc:
            scc_index[v] = i

    num_sccs = len(sccs)
    cond_graph = defaultdict(set)
    cond_indegree = [0] * num_sccs

    for v in universe:
        vi = scc_index[v]
        for w in graph[v]:
            wi = scc_index[w]
            if vi != wi and wi not in cond_graph[vi]:
                cond_graph[vi].add(wi)
                cond_indegree[wi] += 1

    # Representative for each SCC
    scc_reps = []
    scc_members = []
    for i, scc in enumerate(sccs):
        scc_reps.append(min(scc))
        scc_members.append(sorted(scc))

    # Kahn's algorithm with lex tie-breaking by representative
    import heapq
    queue = []
    for i in range(num_sccs):
        if cond_indegree[i] == 0:
            heapq.heappush(queue, (scc_reps[i], i))

    order = []
    while queue:
        rep, i = heapq.heappop(queue)
        for v in scc_members[i]:
            order.append(v)
        for j in cond_graph[i]:
            cond_indegree[j] -= 1
            if cond_indegree[j] == 0:
                heapq.heappush(queue, (scc_reps[j], j))

    return json.dumps({"order": order, "cycles": cycles}, separators=(",", ":"))

if __name__ == "__main__":
    print(solve(sys.stdin.read().splitlines()))
